            ctr[i] = 3
        print(random.choice('01') if ctr[i] else ' ', end='')
        ctr[i] = max(0, ctr[i] - 1)
    print()

def list_to_text(items):
    if len(items) < 3:
        return ' and '.join(items)
    return ', '.join(items[:-1]) + ', and ' + items[-1]
tests = [['a', 'b', 'c'], ['x', 'y'], ['z'], []]
for t in tests:
    print(repr(list_to_text(t)))
